    52→const FJumpMapLayout* UJumpMapLayoutDataAsset::GetLayoutByName(const FString& Name) const
    53→{
    54→	for (const FJumpMapLayout& Layout : BuiltInLayouts)
    55→	{
    56→		if (Layout.LayoutName == Name)
    57→		{
    58→			return &Layout;
    59→		}
    60→	}
    61→	return nullptr;
    62→}
    63→
    64→const FJumpMapLayout* UJumpMapLayoutDataAsset::GetLayoutByNameIncludingUser(const FString& Name) const
    65→{
    66→	// 내장 레이아웃 먼저 검색
    67→	const FJumpMapLayout* BuiltIn = GetLayoutByName(Name);
    68→	if (BuiltIn)
    69→	{
    70→		return BuiltIn;
    71→	}
    72→
    73→	// 유저 레이아웃 검색
    74→	if (!bUserLayoutsCached)
    75→	{
    76→		ScanUserJumpMapLayouts(CachedUserLayouts);
    77→		bUserLayoutsCached = true;
    78→	}
    79→
    80→	for (const FJumpMapLayout& Layout : CachedUserLayouts)
    81→	{
    82→		if (Layout.LayoutName == Name)
    83→		{
    84→			return &Layout;
    85→		}
    86→	}
    87→
    88→	return nullptr;
    89→}
