    91→TArray<FString> UJumpMapLayoutDataAsset::GetAllLayoutNames() const
    92→{
    93→	TArray<FString> AllNames;
    94→
    95→	for (const FJumpMapLayout& Layout : BuiltInLayouts)
    96→	{
    97→		AllNames.Add(Layout.LayoutName);
    98→	}
    99→
   100→	if (!bUserLayoutsCached)
   101→	{
   102→		ScanUserJumpMapLayouts(CachedUserLayouts);
   103→		bUserLayoutsCached = true;
   104→	}
   105→
   106→	for (const FJumpMapLayout& Layout : CachedUserLayouts)
   107→	{
   108→		AllNames.Add(Layout.LayoutName);
   109→	}
   110→
   111→	return AllNames;
   112→}
