    11→AJumpMapKillZoneActor::AJumpMapKillZoneActor()
    12→{
    13→	KillTrigger = CreateDefaultSubobject<UBoxComponent>(TEXT("KillTrigger"));
    14→	KillTrigger->SetupAttachment(RootComp);
    15→	KillTrigger->SetBoxExtent(FVector(500.f, 500.f, 50.f));
    16→	KillTrigger->SetCollisionProfileName(TEXT("OverlapAllDynamic"));
    17→	KillTrigger->SetGenerateOverlapEvents(true);
    18→
    19→	// 킬존은 보이지 않아야 함
