    24→void AJumpMapKillZoneActor::BeginPlay()
    25→{
    26→	Super::BeginPlay();
    27→
    28→	if (HasAuthority())
    29→	{
    30→		KillTrigger->OnComponentBeginOverlap.AddDynamic(this, &AJumpMapKillZoneActor::OnKillOverlap);
    31→	}
    32→}
    33→
    34→void AJumpMapKillZoneActor::OnKillOverlap(UPrimitiveComponent* OverlappedComp, AActor* OtherActor,
    35→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
    36→{
    37→	if (!HasAuthority()) return;
    38→
    39→	AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(OtherActor);
    40→	if (!Character || Character->IsEliminated()) return;
    41→
    42→	UWorld* World = GetWorld();
    43→	if (!World) return;
    44→
    45→	AWjWorldGameModePlay* GameMode = Cast<AWjWorldGameModePlay>(World->GetAuthGameMode());
    46→	if (!GameMode) return;
    47→
    48→	UWjWorldGameRuleJumpMap* GameRule = GameMode->GetCurrentGameRule<UWjWorldGameRuleJumpMap>();
    49→	if (GameRule)
    50→	{
    51→		GameRule->OnPlayerDied(Character);
    52→	}
    53→
    54→	UE_LOG(LogWjWorld, Log, TEXT("JumpMapKillZone: Player [%s] hit kill zone"), *Character->GetName());
    55→}
