    19→void AJumpMapMovingPlatformActor::Tick(float DeltaTime)
    20→{
    21→	Super::Tick(DeltaTime);
    22→
    23→	// 정지 상태 처리
    24→	if (bIsPaused)
    25→	{
    26→		PauseTimer -= DeltaTime;
    27→		if (PauseTimer <= 0.f)
    28→		{
    29→			bIsPaused = false;
    30→			bMovingToTarget = !bMovingToTarget;
    31→		}
    32→		return;
    33→	}
    34→
    35→	const FVector CurrentLocation = GetActorLocation();
    36→	const FVector& Destination = bMovingToTarget ? TargetLocation : OriginalLocation;
    37→
    38→	const FVector NewLocation = FMath::VInterpConstantTo(CurrentLocation, Destination, DeltaTime, MoveSpeed);
    39→	SetActorLocation(NewLocation);
    40→
    41→	// 도착 체크
    42→	if (FVector::DistSquared(NewLocation, Destination) < 1.f)
    43→	{
    44→		SetActorLocation(Destination);
    45→		bIsPaused = true;
    46→		PauseTimer = PauseTime;
    47→	}
    48→}
