     9→int32 UJumpMapLayoutDataAsset::ScanUserJumpMapLayouts(TArray<FJumpMapLayout>& OutUserLayouts) const
    10→{
    11→	OutUserLayouts.Empty();
    12→
    13→	FString UserLayoutDir = GetUserJumpMapLayoutDirectory();
    14→
    15→	IFileManager& FileManager = IFileManager::Get();
    16→	if (!FileManager.DirectoryExists(*UserLayoutDir))
    17→	{
    18→		UE_LOG(LogWjWorld, Log, TEXT("ScanUserJumpMapLayouts: User layout directory does not exist: %s"), *UserLayoutDir);
    19→		return 0;
    20→	}
    21→
    22→	TArray<FString> FoundFiles;
    23→	FileManager.FindFiles(FoundFiles, *UserLayoutDir, TEXT("*.csv"));
    24→
    25→	for (const FString& FileName : FoundFiles)
    26→	{
    27→		FString FullPath = UserLayoutDir / FileName;
    28→		FString FileContent;
    29→
    30→		if (!FFileHelper::LoadFileToString(FileContent, *FullPath))
    31→		{
    32→			UE_LOG(LogWjWorld, Warning, TEXT("ScanUserJumpMapLayouts: Failed to read file: %s"), *FullPath);
    33→			continue;
    34→		}
    35→
    36→		FJumpMapLayout Layout;
    37→		if (ParseLayoutCSV(FileContent, Layout))
    38→		{
    39→			// 레이아웃 이름이 없으면 파일명 사용
    40→			if (Layout.LayoutName.IsEmpty())
    41→			{
    42→				Layout.LayoutName = FString::Printf(TEXT("User_%s"), *FPaths::GetBaseFilename(FileName));
    43→			}
    44→			OutUserLayouts.Add(Layout);
    45→			UE_LOG(LogWjWorld, Log, TEXT("ScanUserJumpMapLayouts: Found user layout '%s'"), *Layout.LayoutName);
    46→		}
    47→	}
    48→
    49→	return OutUserLayouts.Num();
    50→}
    51→
    52→const FJumpMapLayout* UJumpMapLayoutDataAsset::GetLayoutByName(const FString& Name) const
    53→{
    54→	for (const FJumpMapLayout& Layout : BuiltInLayouts)
    55→	{
    56→		if (Layout.LayoutName == Name)
    57→		{
