   127→
   128→bool UJumpMapLayoutDataAsset::ParseLayoutCSV(const FString& FileContent, FJumpMapLayout& OutLayout) const
   129→{
   130→	TArray<FString> Lines;
   131→	FileContent.ParseIntoArrayLines(Lines);
   132→
   133→	bool bHeaderParsed = false;
   134→
   135→	for (const FString& Line : Lines)
   136→	{
   137→		if (Line.IsEmpty()) continue;
   138→
   139→		// 메타데이터 라인 (#META:Key:Value)
   140→		if (Line.StartsWith(TEXT("#")))
   141→		{
   142→			if (Line.StartsWith(TEXT("#META:MapName:")))
   143→			{
   144→				OutLayout.LayoutName = Line.RightChop(14); // "#META:MapName:" 길이 = 14
   145→				OutLayout.LayoutName.TrimStartAndEndInline();
   146→			}
   147→			continue;
   148→		}
   149→
   150→		// CSV 헤더 행 건너뛰기
   151→		if (!bHeaderParsed && Line.Contains(TEXT("ObjectId")))
   152→		{
   153→			bHeaderParsed = true;
   154→			continue;
   155→		}
   156→
   157→		// 데이터 행 파싱: ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ
   158→		TArray<FString> Values;
   159→		Line.ParseIntoArray(Values, TEXT(","), true);
   160→
   161→		if (Values.Num() < 10)
   162→		{
   163→			UE_LOG(LogWjWorld, Warning, TEXT("ParseLayoutCSV: Skipping line with insufficient columns (%d): %s"),
   164→				Values.Num(), *Line);
   165→			continue;
   166→		}
   167→
   168→		FJumpMapLayoutEntry Entry;
   169→		Entry.ObjectId = FName(*Values[0].TrimStartAndEnd());
   170→
   171→		FVector Location;
   172→		Location.X = FCString::Atof(*Values[1]);
   173→		Location.Y = FCString::Atof(*Values[2]);
   174→		Location.Z = FCString::Atof(*Values[3]);
   175→
   176→		FRotator Rotation;
   177→		Rotation.Pitch = FCString::Atof(*Values[4]);
   178→		Rotation.Yaw = FCString::Atof(*Values[5]);
   179→		Rotation.Roll = FCString::Atof(*Values[6]);
   180→
   181→		FVector Scale;
   182→		Scale.X = FCString::Atof(*Values[7]);
   183→		Scale.Y = FCString::Atof(*Values[8]);
   184→		Scale.Z = FCString::Atof(*Values[9]);
   185→
   186→		Entry.Transform = FTransform(Rotation, Location, Scale);
   187→		OutLayout.Objects.Add(Entry);
   188→	}
   189→
   190→	UE_LOG(LogWjWorld, Log, TEXT("ParseLayoutCSV: Parsed %d objects for layout '%s'"),
   191→		OutLayout.Objects.Num(), *OutLayout.LayoutName);
   192→	return OutLayout.Objects.Num() > 0;
   193→}
