    41→void AJumpMapRotatingObstacleActor::OnHitOverlap(UPrimitiveComponent* OverlappedComp, AActor* OtherActor,
    42→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
    43→{
    44→	if (!HasAuthority()) return;
    45→
    46→	AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(OtherActor);
    47→	if (!Character || Character->IsEliminated()) return;
    48→
    49→	if (bKillOnHit)
    50→	{
    51→		UWorld* World = GetWorld();
    52→		if (World)
    53→		{
    54→			AWjWorldGameModePlay* GameMode = Cast<AWjWorldGameModePlay>(World->GetAuthGameMode());
    55→			if (GameMode)
    56→			{
    57→				UWjWorldGameRuleJumpMap* GameRule = GameMode->GetCurrentGameRule<UWjWorldGameRuleJumpMap>();
    58→				if (GameRule)
    59→				{
    60→					GameRule->OnPlayerDied(Character);
    61→				}
    62→			}
    63→		}
    64→		UE_LOG(LogWjWorld, Log, TEXT("JumpMapRotatingObstacle: Killed player [%s]"), *Character->GetName());
    65→	}
    66→	else
    67→	{
    68→		// 넉백 방향: 장애물 중심에서 캐릭터 방향
    69→		FVector KnockbackDir = (Character->GetActorLocation() - GetActorLocation()).GetSafeNormal();
    70→		KnockbackDir.Z = FMath::Max(KnockbackDir.Z, 0.3f); // 약간의 상향 넉백
    71→		KnockbackDir.Normalize();
    72→
    73→		Character->LaunchCharacter(KnockbackDir * KnockbackForce, true, true);
    74→		UE_LOG(LogWjWorld, Log, TEXT("JumpMapRotatingObstacle: Knocked back player [%s]"), *Character->GetName());
    75→	}
    76→}
