   116→void UWjWorldGameRuleJumpMap::OnGameStart()
   117→{
   118→	if (!HasAuthority()) return;
   119→
   120→	Super::OnGameStart();
   121→
   122→	bIsGameStarted = true;
   123→	ElapsedTime = 0.f;
   124→
   125→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Game Started - Players: %d, TimeLimit: %.1f"),
   126→		TotalPlayerCount, TimeLimit);
   127→
   128→	// 엣지 케이스: 플레이어 없음
   129→	if (TotalPlayerCount <= 0)
   130→	{
   131→		UE_LOG(LogWjWorld, Warning, TEXT("GameRuleJumpMap: No players, ending game"));
   132→		bGameOverConditionMet = true;
   133→		WinnerPlayer = nullptr;
   134→		OnGameEnd();
   135→		return;
   136→	}
   137→}
   138→
   139→void UWjWorldGameRuleJumpMap::OnGameEnd()
   140→{
   141→	if (!HasAuthority()) return;
   142→
   143→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   144→	if (GameState)
   145→	{
   146→		// 승자 결정: 가장 빠른 완주 시간
   147→		if (!WinnerPlayer.IsValid())
   148→		{
   149→			float BestTime = MAX_FLT;
   150→			for (const auto& WeakPS : AllPlayers)
   151→			{
   152→				if (!WeakPS.IsValid()) continue;
   153→				AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   154→				UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   155→				if (PlayerData && PlayerData->HasFinished() && PlayerData->GetFinishTime() < BestTime)
   156→				{
   157→					BestTime = PlayerData->GetFinishTime();
   158→					WinnerPlayer = PS;
   159→				}
   160→			}
   161→		}
   162→
   163→		if (WinnerPlayer.IsValid())
   164→		{
   165→			GameState->SetGameResult(WinnerPlayer->GetPlayerName(), true);
   166→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Winner: %s"), *WinnerPlayer->GetPlayerName());
   167→		}
   168→		else
   169→		{
   170→			GameState->SetGameResult(TEXT(""), false);
   171→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: No winner (time expired)"));
   172→		}
   173→	}
   174→
   175→	// 스폰된 게임플레이 액터 정리
   176→	for (const auto& WeakActor : SpawnedGameplayActors)
   177→	{
   178→		if (WeakActor.IsValid())
   179→		{
   180→			WeakActor->Destroy();
   181→		}
   182→	}
   183→	SpawnedGameplayActors.Empty();
   184→
   185→	Super::OnGameEnd();
   186→}
