   188→void UWjWorldGameRuleJumpMap::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   189→{
   190→	Super::OnPlayerJoined(Player);
   191→
   192→	if (!HasAuthority() || !Player) return;
   193→
   194→	AllPlayers.Add(Player);
   195→	TotalPlayerCount++;
   196→
   197→	UpdateGameData();
   198→
   199→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player Joined - %s, Total: %d"),
   200→		*Player->GetPlayerName(), TotalPlayerCount);
   201→}
   202→
   203→void UWjWorldGameRuleJumpMap::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   204→{
   205→	Super::OnPlayerLeft(Player);
   206→
   207→	if (!HasAuthority() || !Player) return;
   208→
   209→	AllPlayers.Remove(Player);
   210→	TotalPlayerCount--;
   211→
   212→	UpdateGameData();
   213→
   214→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player Left - %s, Total: %d"),
   215→		*Player->GetPlayerName(), TotalPlayerCount);
   216→
   217→	// 모든 플레이어 이탈
   218→	if (TotalPlayerCount <= 0)
   219→	{
   220→		bGameOverConditionMet = true;
   221→		WinnerPlayer = nullptr;
   222→		OnGameEnd();
   223→		return;
   224→	}
   225→
   226→	// 남은 플레이어가 모두 완주했는지 체크
   227→	int32 ActivePlayers = 0;
   228→	for (const auto& WeakPS : AllPlayers)
   229→	{
   230→		if (!WeakPS.IsValid()) continue;
   231→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   232→		if (!PlayerData || !PlayerData->HasFinished())
   233→		{
   234→			ActivePlayers++;
   235→		}
   236→	}
   237→
   238→	if (ActivePlayers == 0 && FinishedPlayerCount > 0)
   239→	{
   240→		bGameOverConditionMet = true;
   241→		OnGameEnd();
   242→	}
   243→}
