   245→void UWjWorldGameRuleJumpMap::OnPlayerDied(AWjWorldCharacterPlay* Character)
   246→{
   247→	if (!HasAuthority() || !Character) return;
   248→
   249→	AWjWorldPlayerStatePlay* PS = Character->GetPlayerState<AWjWorldPlayerStatePlay>();
   250→	if (!PS) return;
   251→
   252→	// 이미 완주한 플레이어는 무시
   253→	UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   254→	if (!PlayerData || PlayerData->HasFinished()) return;
   255→
   256→	// 사망 횟수 증가
   257→	PlayerData->IncrementDeathCount();
   258→
   259→	int32 CheckpointIdx = PlayerData->GetCurrentCheckpointIndex();
   260→
   261→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player died: %s (Deaths: %d, Checkpoint: %d)"),
   262→		*PS->GetPlayerName(), PlayerData->GetDeathCount(), CheckpointIdx);
   263→
   264→	// 리스폰
   265→	RespawnPlayerAtCheckpoint(Character, CheckpointIdx);
   266→}
