   268→void UWjWorldGameRuleJumpMap::RespawnPlayerAtCheckpoint(AWjWorldCharacterPlay* Character, int32 CheckpointIndex)
   269→{
   270→	if (!Character) return;
   271→
   272→	FVector RespawnLocation;
   273→	if (CheckpointIndex >= 0 && CheckpointIndex < CheckpointLocations.Num())
   274→	{
   275→		RespawnLocation = CheckpointLocations[CheckpointIndex];
   276→	}
   277→	else
   278→	{
   279→		RespawnLocation = StartLocation;
   280→	}
   281→
   282→	// 약간 위에 스폰 (바닥 충돌 방지)
   283→	RespawnLocation.Z += 100.f;
   284→
   285→	Character->SetActorLocation(RespawnLocation);
   286→
   287→	// 속도 초기화
   288→	if (UCharacterMovementComponent* MC = Character->GetCharacterMovement())
   289→	{
   290→		MC->StopMovementImmediately();
   291→	}
   292→
   293→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Respawned at checkpoint %d (%s)"),
   294→		CheckpointIndex, *RespawnLocation.ToString());
   295→}
   296→
   297→void UWjWorldGameRuleJumpMap::OnPlayerFinished(AWjWorldCharacterPlay* Character)
   298→{
   299→	if (!HasAuthority() || !Character) return;
   300→
   301→	AWjWorldPlayerStatePlay* PS = Character->GetPlayerState<AWjWorldPlayerStatePlay>();
   302→	if (!PS) return;
   303→
   304→	UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   305→	if (!PlayerData || PlayerData->HasFinished()) return;
   306→
   307→	// 완주 기록
   308→	PlayerData->SetFinished(ElapsedTime);
   309→	FinishedPlayerCount++;
   310→
   311→	// GameData에 완주 순서 추가
   312→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   313→	if (GameState)
   314→	{
   315→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   316→		if (GameData)
   317→		{
   318→			FJumpMapPlayerFinish FinishInfo;
   319→			FinishInfo.PlayerName = PS->GetPlayerName();
   320→			FinishInfo.FinishTime = ElapsedTime;
   321→			GameData->AddPlayerFinish(FinishInfo);
   322→			GameData->SetFinishedPlayerCount(FinishedPlayerCount);
   323→		}
   324→	}
   325→
   326→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player finished: %s (Time: %.2f, Order: %d/%d)"),
   327→		*PS->GetPlayerName(), ElapsedTime, FinishedPlayerCount, TotalPlayerCount);
   328→
   329→	// 첫 번째 완주자가 승자
   330→	if (!WinnerPlayer.IsValid())
   331→	{
   332→		WinnerPlayer = PS;
   333→	}
   334→
   335→	// 모든 플레이어가 완주했는지 체크
   336→	int32 ActivePlayers = 0;
   337→	for (const auto& WeakPS : AllPlayers)
   338→	{
   339→		if (!WeakPS.IsValid()) continue;
   340→		UJumpMapPlayerDataComponent* PD = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   341→		if (!PD || !PD->HasFinished())
   342→		{
   343→			ActivePlayers++;
   344→		}
   345→	}
   346→
   347→	if (ActivePlayers == 0)
   348→	{
   349→		bGameOverConditionMet = true;
   350→		OnGameEnd();
   351→	}
   352→}
   353→
   354→bool UWjWorldGameRuleJumpMap::CheckWinCondition() const
   355→{
   356→	if (!bIsGameStarted) return false;
   357→	return bGameOverConditionMet;
   358→}
   359→
   360→AWjWorldPlayerStatePlay* UWjWorldGameRuleJumpMap::GetWinner() const
   361→{
   362→	return WinnerPlayer.Get();
   363→}
   364→
   365→void UWjWorldGameRuleJumpMap::TickGameRule(float DeltaTime)
   366→{
   367→	if (!HasAuthority()) return;
   368→	if (!bIsGameStarted || bGameOverConditionMet) return;
   369→
   370→	// 경과 시간 업데이트
   371→	ElapsedTime += DeltaTime;
   372→
   373→	// GameData 업데이트
   374→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   375→	if (GameState)
   376→	{
   377→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   378→		if (GameData)
   379→		{
   380→			GameData->SetElapsedTime(ElapsedTime);
   381→		}
   382→	}
   383→
   384→	// 낙하 플레이어 체크
   385→	for (const auto& WeakPS : AllPlayers)
   386→	{
   387→		if (!WeakPS.IsValid()) continue;
   388→
   389→		APawn* Pawn = WeakPS->GetPawn();
   390→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Pawn);
   391→		if (!Character) continue;
   392→
   393→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   394→		if (PlayerData && PlayerData->HasFinished()) continue;
   395→
   396→		if (Character->GetActorLocation().Z < FallThresholdZ)
   397→		{
   398→			OnPlayerDied(Character);
   399→		}
   400→	}
   401→
   402→	// 시간 제한 체크
   403→	if (TimeLimit > 0.f && ElapsedTime >= TimeLimit)
   404→	{
   405→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Time limit reached (%.1f)"), TimeLimit);
   406→		bGameOverConditionMet = true;
   407→		OnGameEnd();
   408→	}
   409→}
   410→
   411→void UWjWorldGameRuleJumpMap::UpdateGameData()
   412→{
   413→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   414→	if (!GameState) return;
   415→
   416→	UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   417→	if (!GameData) return;
   418→
   419→	GameData->SetTotalPlayerCount(TotalPlayerCount);
   420→	GameData->SetFinishedPlayerCount(FinishedPlayerCount);
   421→}
