    22→
    23→void UWjWorldGameRuleJumpMap::Initialize(AWjWorldGameModePlay* InGameMode)
    24→{
    25→	Super::Initialize(InGameMode);
    26→
    27→	GameDataComponentClass = UJumpMapGameDataComponent::StaticClass();
    28→	PlayerDataComponentClass = UJumpMapPlayerDataComponent::StaticClass();
    29→
    30→	// MapOption에서 레이아웃 이름 파싱
    31→	if (InGameMode)
    32→	{
    33→		const FString& MapOpt = InGameMode->GetMapOption();
    34→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: MapOption = '%s'"), *MapOpt);
    35→	}
    36→
    37→	// 레이아웃 로드 및 게임플레이 액터 스폰
    38→	LoadLayoutAndSpawnActors();
    39→
    40→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Initialized (TimeLimit=%.1f, FallThreshold=%.1f)"),
    41→		TimeLimit, FallThresholdZ);
    42→}
    43→
    44→void UWjWorldGameRuleJumpMap::LoadLayoutAndSpawnActors()
    45→{
    46→	UWorld* World = GetWorld();
    47→	if (!World) return;
    48→
    49→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    50→	if (!DevSettings) return;
    51→
    52→	// JumpMap 배치 카탈로그에서 레이아웃 로드
    53→	// 맵에 이미 배치된 체크포인트/엔드 액터를 수집
    54→	for (TActorIterator<AJumpMapCheckpointActor> It(World); It; ++It)
    55→	{
    56→		AJumpMapCheckpointActor* Checkpoint = *It;
    57→		if (Checkpoint)
    58→		{
    59→			int32 Order = Checkpoint->CheckpointOrder;
    60→			// 배열 크기 확보
    61→			if (CheckpointLocations.Num() <= Order)
    62→			{
    63→				CheckpointLocations.SetNum(Order + 1);
    64→			}
    65→			CheckpointLocations[Order] = Checkpoint->GetActorLocation();
    66→
    67→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Checkpoint %d at %s"),
    68→				Order, *Checkpoint->GetActorLocation().ToString());
    69→		}
    70→	}
    71→
    72→	// 엔드 액터에서 스타트 위치 확인
    73→	for (TActorIterator<AJumpMapEndActor> It(World); It; ++It)
    74→	{
    75→		AJumpMapEndActor* EndActor = *It;
    76→		if (EndActor)
    77→		{
    78→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: End actor at %s"),
    79→				*EndActor->GetActorLocation().ToString());
    80→		}
    81→	}
    82→
    83→	// 플레이어 스타트에서 시작 위치 가져오기
    84→	AActor* PlayerStart = UGameplayStatics::GetActorOfClass(World, APlayerStart::StaticClass());
    85→	if (PlayerStart)
    86→	{
    87→		StartLocation = PlayerStart->GetActorLocation();
    88→	}
    89→
