   365→void UWjWorldGameRuleJumpMap::TickGameRule(float DeltaTime)
   366→{
   367→	if (!HasAuthority()) return;
   368→	if (!bIsGameStarted || bGameOverConditionMet) return;
   369→
   370→	// 경과 시간 업데이트
   371→	ElapsedTime += DeltaTime;
   372→
   373→	// GameData 업데이트
   374→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   375→	if (GameState)
   376→	{
   377→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   378→		if (GameData)
   379→		{
   380→			GameData->SetElapsedTime(ElapsedTime);
   381→		}
   382→	}
   383→
   384→	// 낙하 플레이어 체크
   385→	for (const auto& WeakPS : AllPlayers)
   386→	{
   387→		if (!WeakPS.IsValid()) continue;
   388→
   389→		APawn* Pawn = WeakPS->GetPawn();
   390→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Pawn);
   391→		if (!Character) continue;
   392→
   393→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   394→		if (PlayerData && PlayerData->HasFinished()) continue;
   395→
   396→		if (Character->GetActorLocation().Z < FallThresholdZ)
   397→		{
   398→			OnPlayerDied(Character);
   399→		}
   400→	}
   401→
   402→	// 시간 제한 체크
   403→	if (TimeLimit > 0.f && ElapsedTime >= TimeLimit)
   404→	{
   405→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Time limit reached (%.1f)"), TimeLimit);
   406→		bGameOverConditionMet = true;
   407→		OnGameEnd();
   408→	}
   409→}
   410→
   411→void UWjWorldGameRuleJumpMap::UpdateGameData()
   412→{
   413→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   414→	if (!GameState) return;
   415→
   416→	UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   417→	if (!GameData) return;
   418→
   419→	GameData->SetTotalPlayerCount(TotalPlayerCount);
   420→	GameData->SetFinishedPlayerCount(FinishedPlayerCount);
   421→}
